sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var c = this;

  c.selectedYear = "";

  function atualizarIndicador() {
    c.server.get({ selectedYear: c.selectedYear }).then(function(response) {
      c.data = response.data;
      // console.log("Indicador Investimento atualizado:", c.selectedYear, c.data);
    });
  }

  // Escuta o evento de filtro de ano
  $rootScope.$on('anoSelecionado', function(event, ano) {
    c.selectedYear = ano;
    atualizarIndicador();
  });

  // Carregamento inicial
  atualizarIndicador();
}

sp_widget.css:
.financial-widget {
  font-family: Roboto;
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  margin-top: 4rem;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
}

sp_widget.script:
(function() {
    input = input || {};
    var table = 'x_sded9_portal_t_0_investimento';
    var selectedYear = input.selectedYear || "";

    // 1. Busca o ano mais recente se nenhum for selecionado
    if (!selectedYear) {
        var g = new GlideRecord(table);
        g.orderByDesc('u_ano');
        g.setLimit(1);
        g.query();
        if (g.next())
            selectedYear = g.getValue('u_ano');
    }

    data.selectedYear = selectedYear;

    // Valor padrão
    data.indicator = {
        value: '0%', 
        label: 'Percentual: ' + (selectedYear ? selectedYear : 'N/A')
    };

    // 2. Busca o dado na tabela
    var gr = new GlideRecord(table);

    if (selectedYear) {
        gr.addQuery('u_ano', selectedYear);
    }

    gr.orderByDesc('sys_created_on');
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {
        var anoReal = gr.getValue('u_ano');
        // Pega o valor bruto (ex: "12.56")
        var valorBruto = gr.getValue('percentual_da_rcl_investimento_empenhado') || '0'; 

        // Apenas troca ponto por vírgula e adiciona %
        // Se vier do banco como "12.568", vira "12,568%"
        var valorFinal = valorBruto.replace('.', ',') + '%';

        data.indicator.value = valorFinal; 
        data.indicator.label = 'Percentual ' + anoReal + ':';
        data.selectedYear = anoReal;
    }

    // A função formatarMoedaAbreviada foi removida pois não é mais necessária.

})();
